#include <iostream>
using namespace std;
int main(){
    int n;
    cin >> n;
    int array[n+1][2],tmp[n+1],calc=1,ans=1;
    for(int i=1;i<=n;i++){
        cin >> array[i][0];
        cin >> array[i][1];
        tmp[i]=i;
    }
    for(int i=1;i<=n;i++){
        int temp=i;
        for(int j=i+1;j<=n;j++){
            if(array[tmp[temp]][1] > array[tmp[j]][1])temp=j;
        }
        int t = tmp[i];
        tmp[i] = tmp[temp];
        tmp[temp] = t;
    }
    for(int i=2;i<=n;i++){
        if(array[tmp[i]][0] >= array[tmp[calc]][1]){ans++;calc=i;}
    }
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void swap_values(int* x, int* y);
void swap_addresses(int*& x, int*& y);

int main() {
    int x = 1, y = 2, *a, *b;
    swap_values(&x, &y);
    cout << x << y << endl;
    *a = 1;
    *b = 2;
    swap_addresses(a, b);
    cout << x << y;
    return 0;
}

void swap_addresses(int*& x, int*& y) {
    int* tmp = x;
    x = y;
    y = tmp;
}

void swap_values(int* x, int* y) {
    int tmp;
    tmp = *x;
    *x = *y;
    *y = tmp;
}

