    if(a==1 && b==1)return 0;
    node tmp;
    tmp.x=dots[0][0];tmp.y=dots[0][1];tmp.dest=0;
    pipe.push(tmp);
    const int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};
    while(!pipe.empty()){
        tmp=pipe.front();
        pipe.pop();
        for(int i=0;i<4;i++){
            if(tmp.x+dx[i]<0 || tmp.y+dy[i]<0 || tmp.x+dx[i]>=a || tmp.y+dy[i]>=b)continue;
