            if(chr[tmp.x+dx[i]][tmp.y+dy[i]]!='#'){
                if(tmp.x+dx[i]!=dots[1][0] && tmp.y+dy[i]!=dots[1][1]){
                    node ttmp;
                    ttmp.x=tmp.x+dx[i];
                    ttmp.y=tmp.y+dy[i];
                    ttmp.dest=tmp.dest+1;
                    mapps[ttmp.x][ttmp.y]=1;
                    pipe.push(ttmp);
                }else{
                    tmp.dest++;
                    return tmp.dest;
                }
            }else continue;
        }
    }
    return -1;
}

