int bfs(const mapp& flood,visited& maps){
    node tmp;
    if(a==0 && b==0){return 0;}
    int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};
    stack<int> fin_ans;
    while(!s.empty()){
        tmp=s.front();
        s.pop();
        maps[tmp.x][tmp.y]=1;
        int nx,ny;
        for(int i=0;i<4;i++){
            nx=tmp.x+dx[i];ny=tmp.y+dy[i];
