                node ttmp;
                ttmp.x=nx;ttmp.y=ny;ttmp.neigh=tmp.neigh+1;
                s.push(ttmp);
                fin_ans.push(ttmp.neigh);
                maps[nx][ny]=1;
            }
        }
    }
    return fin_ans.top();

}

