int a,b;
struct bucket{
    int x,y,dist;
};queue<bucket> s;
bucket bfs(const mapp& m,ppt& visited){
    int dx[4]={1,-1,0,0},dy[4]={0,0,-1,1};
    bucket cur;
    cur.x=0;cur.y=0;cur.dist=0;
    visited[0][0]=true;
    s.push(cur);
    if(cur.x==a-1 && cur.y==b-1){return cur;}
    while(!s.empty()){
        cur = s.front();
        s.pop();
        for(int i=0;i<4;i++){
            int nx=cur.x+dx[i];
            int ny=cur.y+dy[i];
            if(nx<0 || ny<0 || nx>=a || ny>=b)continue;
            if(visited[nx][ny]!=1){
                if(m[nx][ny]!='#'){
                        if(nx==a-1 && ny==b-1){
