                            tmp.x=nx;tmp.y=ny;
                            visited[tmp.x][tmp.y]=true;
                            tmp.dist=cur.dist+1;
                            s.push(tmp);
                        }
                }else continue;
            }else continue;
        }
    }
    cur.dist=-1;cur.x=-1;cur.y=-1;
    return cur;
}

