                    ttmp.x=tmp.x+dx[i];
                    ttmp.y=tmp.y+dy[i];
                    ttmp.dest=tmp.dest+1;
                    mapps[ttmp.x][ttmp.y]=1;
                    pipe.push(ttmp);
                }
            }else continue;
        }
    }
    return -1;
}

